// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    BaseEscalationManager c;
    function setUp() public { c = new BaseEscalationManager(address(this)); }

    function testFuzz_property(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {

        bool okRef;
        int256 refVal;
        try c.getPrice(identifier, time, ancillaryData) returns (int256 v) {
            okRef = true;
            refVal = v;
        } catch {
            okRef = false;
            refVal = int256(0);
        }

        assertTrue(okRef && refVal == 0);
    }
}
